<?php require_once __DIR__.'/../includes/functions.php';require_admin();$q=db()->query('SELECT r.*,a.name rater,b.name ratee FROM ratings r JOIN users a ON a.id=r.rater_id JOIN users b ON b.id=r.ratee_id ORDER BY r.created_at DESC');page_start('Student feedback',true); ?><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Partner</th><th>Rating</th><th>Feedback</th><th>Date</th></tr></thead><tbody><?php foreach($q as $r): ?><tr><td><?= e($r['rater']) ?></td><td><?= e($r['ratee']) ?></td><td><?= str_repeat('★',(int)$r['rating']) ?></td><td><?= e($r['feedback']) ?></td><td><?= e(substr($r['created_at'],0,10)) ?></td></tr><?php endforeach ?></tbody></table></div></div><?php page_end(); ?>
